cd ~/development/.tmp/stallion-scan/mirror && git ls-tree -r --name-only main | grep -E '^infra/|tfstate|\.env|vars' | cat; echo ==; git show main:infra/terraform.tfstate | node -e '
let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);const out=new Set();
const re=/secret|token|key|password/i;
function walk(o,p){if(o&&typeof o==="object"){for(const [k,v] of Object.entries(o)){const np=p+"."+k;
if(re.test(k)){const filled=v!==null&&v!==""&&!(Array.isArray(v)&&v.length===0)&&!(typeof v==="object"&&!Array.isArray(v)&&Object.keys(v).length===0);out.add(np.replace(/\.\d+(?=\.|$)/g,"[]")+(filled?"  (non-empty "+typeof v+")":"  (empty)"));}
walk(v,np);}}}
for(const r of j.resources||[]){walk(r.instances,r.type+"."+r.name)}
walk(j.outputs,"outputs");
console.log([...out].join("\n"));
console.log("resource types:",[...new Set((j.resources||[]).map(r=>r.type))].join(", "));
console.log("sensitive outputs:",Object.entries(j.outputs||{}).filter(([k,v])=>v.sensitive).map(([k])=>k).join(", "));})'

